  ('d5000000-0000-4000-8000-000000000059', null, 'Never Alone Community Food Pantry', 'A Woodstock nonprofit fighting hunger in Cherokee and nearby counties, where volunteers sort, pack, and distribute groceries.', 'https://www.neveralone.org', 'https://www.google.com/s2/favicons?domain=www.neveralone.org&sz=128', 'food', array['good for crews', 'recurring', 'family friendly'], false, false, 14, 'United States', 'GA', 'Woodstock', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000060', null, 'Umi Feeds', 'An Atlanta food-rescue nonprofit that recovers surplus food and serves healthy meals to people who are hungry and homeless through a mobile market.', 'https://umifeeds.org', 'https://www.google.com/s2/favicons?domain=umifeeds.org&sz=128', 'food', array['good for crews', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- GARDENING
  ('d5000000-0000-4000-8000-000000000061', null, 'Freedom Farmers Market', 'A local organic farmers market at the Carter Center in Atlanta bringing sustainably grown food intown, run with the help of market volunteers.', 'https://freedomfarmersmkt.com', 'https://www.google.com/s2/favicons?domain=freedomfarmersmkt.com&sz=128', 'gardening', array['outdoors', 'good for crews', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000062', null, 'Community Farmers Markets', 'An Atlanta nonprofit building local food infrastructure through neighborhood farmers markets and community garden volunteer workdays.', 'https://cfmatl.org', 'https://www.google.com/s2/favicons?domain=cfmatl.org&sz=128', 'gardening', array['outdoors', 'good for crews', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000063', null, 'Columbus Botanical Garden', 'A botanical garden in Columbus where volunteers tend beds and daylilies, arrange flowers, prune plants, and lead tours.', 'https://www.columbusbotanicalgarden.org', 'https://www.google.com/s2/favicons?domain=www.columbusbotanicalgarden.org&sz=128', 'gardening', array['outdoors', 'physical work', 'recurring'], false, false, 14, 'United States', 'GA', 'Columbus', true, true, 'both', false),
  -- TECH
  ('d5000000-0000-4000-8000-000000000064', null, 'STE(A)M Truck', 'An Atlanta education nonprofit that immerses youth in hands-on STEAM experiences, with volunteers mentoring students in immersive workshops.', 'https://www.steamtruck.org', 'https://www.google.com/s2/favicons?domain=www.steamtruck.org&sz=128', 'tech', array['recurring', 'leadership role', 'counts for school hours'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000065', null, 'Compudopt Atlanta', 'A nonprofit providing free computers and technology education to under-resourced youth, with volunteers running giveaways and classes.', 'https://www.compudopt.org', 'https://www.google.com/s2/favicons?domain=www.compudopt.org&sz=128', 'tech', array['recurring', 'good for crews', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Forest Park', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000066', null, 'PCs for People', 'A digital-equity nonprofit with an Atlanta location, where warehouse volunteers refurbish, test, and prepare computers for people in need.', 'https://www.pcsforpeople.org', 'https://www.google.com/s2/favicons?domain=www.pcsforpeople.org&sz=128', 'tech', array['recurring', 'good for crews'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- VETERANS
  ('d5000000-0000-4000-8000-000000000067', null, 'Purple Heart Homes', 'A veteran-founded nonprofit whose metro Atlanta chapter provides housing solutions for disabled and aging veterans, with volunteer build days.', 'https://www.purplehearthomesusa.org', 'https://www.google.com/s2/favicons?domain=www.purplehearthomesusa.org&sz=128', 'veterans', array['recurring', 'physical work', 'good for crews'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000068', null, 'HeroBox', 'A Peachtree City nonprofit whose volunteers pack and ship care boxes to deployed, injured, aging, and homeless service members and veterans.', 'https://www.herobox.org', 'https://www.google.com/s2/favicons?domain=www.herobox.org&sz=128', 'veterans', array['good for crews', 'family friendly', 'recurring'], false, false, 14, 'United States', 'GA', 'Peachtree City', true, true, 'both', false),
  ('d5000000-0000-4000-8000-000000000069', null, 'Operation One Voice', 'A Georgia-based, volunteer-driven nonprofit supporting wounded and fallen Special Operations Forces and their families through events and programs.', 'https://o1v.org', 'https://www.google.com/s2/favicons?domain=o1v.org&sz=128', 'veterans', array['recurring', 'good for crews', 'leadership role'], false, false, 18, 'United States', 'GA', 'Hoschton', true, true, 'both', false),
  -- ART (round out)
  ('d5000000-0000-4000-8000-000000000070', null, 'Out Front Theatre Company', 'Georgia''s LGBTQIA+ theatre in Atlanta, founded as a volunteer-led effort in 2016, where volunteers of any skill level help produce shows and run events.', 'https://outfronttheatre.com', 'https://www.google.com/s2/favicons?domain=outfronttheatre.com&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('d6000000-0000-4000-8000-000000000001', 'd5000000-0000-4000-8000-000000000001', 'Usher and Help at Horizon Theatre', 'art', 'Volunteers usher, welcome guests, and support hospitality, marketing, and events at Horizon Theatre in Little Five Points, and ushers get to see the show for free. It is a great fit if you love contemporary theater. Roles range from single shows to a regular schedule.', array['recurring', 'creative work'], 16, false, false, true, '3-4 hrs', 'https://www.horizontheatre.com/get-involved/volunteer/', 'https://www.horizontheatre.com/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000002', 'd5000000-0000-4000-8000-000000000002', 'Usher at Synchronicity Theatre', 'art', 'Volunteers usher and help at performances at Synchronicity Theatre in Midtown, a company that uplifts the voices of women and girls; it is also a good way to earn community service hours. If you love live theater, it is a rewarding place to help. Sign up for shifts around the show schedule.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://synchrotheatre.com/support/', 'https://synchrotheatre.com/support/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000003', 'd5000000-0000-4000-8000-000000000003', 'Volunteer at Dad''s Garage', 'art', 'Volunteers help run improv and comedy shows at Dad''s Garage, and in return you see the show free that night and earn credit toward classes, gift certificates, and merch. It is a fun, social way to be part of Atlanta''s comedy scene. Email the patron services team to get started.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://www.dadsgarage.com/get-involved', 'https://www.dadsgarage.com/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000004', 'd5000000-0000-4000-8000-000000000004', 'Usher or Build Sets at Theatrical Outfit', 'art', 'Volunteers usher, organize, build and paint sets, sew costumes, and help with auditions at Theatrical Outfit in downtown Atlanta. There is a role whether you want to be out front or behind the scenes. Contact the volunteer coordinator to find your fit.', array['recurring', 'creative work'], 16, false, false, true, '3-4 hrs', 'https://www.theatricaloutfit.org/work-with-us/volunteer/', 'https://www.theatricaloutfit.org/work-with-us/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000005', 'd5000000-0000-4000-8000-000000000005', 'Make Art with Savannah Kids', 'art', 'Volunteers help lead arts-integrated activities with children through Loop It Up Savannah, which reaches thousands of young people a year. It is a creative, joyful way to work with kids in the Savannah area. Reach out through the site to get connected.', array['recurring', 'creative work', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.loopitupsavannah.com/volunteer.html', 'https://www.loopitupsavannah.com/volunteer.html', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d6000000-0000-4000-8000-000000000006', 'd5000000-0000-4000-8000-000000000006', 'Support Arts Education in Augusta', 'art', 'Volunteers help with classes, performances, and events at Augusta Mini Theatre, Augusta''s community arts school for youth and adults. It is a great fit if you care about affordable access to the arts. Contact the theater to learn about current needs.', array['recurring', 'creative work'], 14, false, false, true, '2-3 hrs', 'https://augustaminitheatre.org/', 'https://augustaminitheatre.org/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('d6000000-0000-4000-8000-000000000007', 'd5000000-0000-4000-8000-000000000007', 'Help at the Marietta Cobb Museum of Art', 'art', 'Volunteers staff the admissions desk, help at special events like Chalktoberfest, assist with art camp, or do outreach at the Marietta Cobb Museum of Art. There is a role for many interests and schedules. It is a friendly way to be part of the Marietta arts scene.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://mariettacobbartmuseum.org/get-involved', 'https://mariettacobbartmuseum.org/get-involved', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d6000000-0000-4000-8000-000000000008', 'd5000000-0000-4000-8000-000000000008', 'Greet Guests at the Hudgens Center', 'art', 'Volunteers greet and care for guests at exhibitions and special events at the Hudgens Center for Art & Learning in Duluth, helping bring art education to Gwinnett County. It is a welcoming role for art lovers. Roles are mostly event-based.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://www.thehudgens.org/get-involved', 'https://www.thehudgens.org/get-involved', '2026-01-01T00:00:00Z', 'Duluth', 'GA'),
  ('d6000000-0000-4000-8000-000000000009', 'd5000000-0000-4000-8000-000000000009', 'Bring Aviation History to Life', 'art', 'Volunteers greet guests, interpret exhibits, and support programs at the Museum of Aviation in Warner Robins, one of the largest aviation museums in the country. Volunteers are at least 17 and commit to a regular weekly shift. It is a great fit if you love history and aircraft.', array['recurring', 'leadership role'], 17, false, false, true, '4 hrs / week', 'https://museumofaviation.org/give/volunteer/', 'https://museumofaviation.org/give/volunteer/', '2026-01-01T00:00:00Z', 'Warner Robins', 'GA'),
  ('d6000000-0000-4000-8000-000000000010', 'd5000000-0000-4000-8000-000000000010', 'Volunteer at the Southern Museum', 'art', 'Volunteers 18 and up help with curatorial work, the library and archives, education, events, and the gift shop at the Southern Museum in Kennesaw. A minimum of 40 hours a year is requested with flexible scheduling. It is a great fit if you love Civil War and railroad history.', array['recurring', 'leadership role'], 18, false, false, true, '3-4 hrs', 'https://southernmuseum.org/join-give/', 'https://southernmuseum.org/join-give/', '2026-01-01T00:00:00Z', 'Kennesaw', 'GA'),
  ('d6000000-0000-4000-8000-000000000011', 'd5000000-0000-4000-8000-000000000011', 'Lead Tours at the Infantry Museum', 'art', 'Volunteers greet guests, explain artifacts, and lead tours (including the World War II Company Street) at the National Infantry Museum in Columbus. It is an integral role in the museum''s daily operation. A great fit if you love military history and meeting people.', array['recurring', 'leadership role'], 16, false, false, true, '3-4 hrs', 'https://nationalinfantrymuseum.org/support/', 'https://nationalinfantrymuseum.org/support/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('d6000000-0000-4000-8000-000000000012', 'd5000000-0000-4000-8000-000000000012', 'Help Preserve Georgia''s Historic Places', 'art', 'Volunteers support programs, historic-property cleanups, office work, and special events with The Georgia Trust for Historic Preservation, the largest statewide preservation nonprofit in the country. It is a great fit if you love history and architecture. Roles range from one-time events to ongoing help.', array['recurring', 'leadership role'], 16, false, false, true, '2-4 hrs', 'https://www.georgiatrust.org/', 'https://www.georgiatrust.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000013', 'd5000000-0000-4000-8000-000000000013', 'Support the Georgia Boy Choir', 'music', 'Volunteers help at concerts, tours, and events for the Georgia Boy Choir, which trains boys and young men in choral excellence. If you love music, it is a rewarding way to support young singers. Roles are mostly event- and production-based.', array['recurring', 'creative work'], 14, false, false, true, '2-3 hrs', 'https://georgiaboychoir.org/', 'https://georgiaboychoir.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000014', 'd5000000-0000-4000-8000-000000000014', 'Chaperone and Help a Youth Choir', 'music', 'Volunteers chaperone rehearsals, help backstage, and support concerts for the Georgia Youth Choir, a premier children''s choir performing across the state. It is a family-friendly way to support young musicians. Great if you love music and working with kids.', array['recurring', 'creative work', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://www.georgiayouthchoir.org/', 'https://www.georgiayouthchoir.org/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d6000000-0000-4000-8000-000000000015', 'd5000000-0000-4000-8000-000000000015', 'Support a Community Chorus', 'music', 'Volunteers help with concerts, events, and operations for The Michael O''Neal Singers, an acclaimed Roswell community chorus. If you love choral music, it is a great way to be part of it behind the scenes. Roles are mostly concert-season based.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://mosingers.com/', 'https://mosingers.com/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('d6000000-0000-4000-8000-000000000016', 'd5000000-0000-4000-8000-000000000016', 'Volunteer with The Atlanta Opera', 'music', 'Volunteers support world-class opera productions, events, and programs with The Atlanta Opera, helping keep costs low while sharing their time and skills. Volunteers contribute thousands of hours a year. It is a great fit if you love music and the performing arts.', array['recurring', 'creative work'], 18, false, false, true, '3-4 hrs', 'https://www.atlantaopera.org/donate/volunteer-your-time/', 'https://www.atlantaopera.org/donate/volunteer-your-time/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000017', 'd5000000-0000-4000-8000-000000000017', 'Help at Savannah Philharmonic Concerts', 'music', 'Volunteers assist at concerts, community programs, and events for the Savannah Philharmonic, coastal Georgia''s professional orchestra and chorus. It is a great way to enjoy and support live orchestral music. Reach out through the site to find current roles.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://savannahphilharmonic.org/', 'https://savannahphilharmonic.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d6000000-0000-4000-8000-000000000018', 'd5000000-0000-4000-8000-000000000018', 'Care for Rescue Dogs and Cats', 'animals', 'Volunteers socialize animals, help at adoption events, and support daily operations at Mostly Mutts, a Kennesaw rescue run almost entirely by volunteers. There are flexible, rewarding roles for many schedules. It is a great fit if you love animals.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://mostlymutts.org/how-to-help/volunteer', 'https://mostlymutts.org/how-to-help/volunteer', '2026-01-01T00:00:00Z', 'Kennesaw', 'GA'),
  ('d6000000-0000-4000-8000-000000000019', 'd5000000-0000-4000-8000-000000000019', 'Help Care for Rescued Horses', 'animals', 'Volunteers help feed, groom, and care for rescued horses at Save the Horses, an all-volunteer farm in Cumming; a free orientation is held the second Saturday of each month. It is hands-on outdoor work for people who love horses. No experience needed to start.', array['outdoors', 'physical work', 'recurring'], 14, false, false, true, '3-4 hrs', 'https://www.savethehorses.org/', 'https://www.savethehorses.org/', '2026-01-01T00:00:00Z', 'Cumming', 'GA'),
  ('d6000000-0000-4000-8000-000000000020', 'd5000000-0000-4000-8000-000000000020', 'Volunteer with Fayette Humane Society', 'animals', 'Volunteers help cats and dogs through the all-volunteer Fayette Humane Society, with roles and projects to fit whatever your skills and schedule allow. It is a flexible way to support animals in your community. Start with the volunteer form on their site.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://fayettehumane.org/get-involved/volunteer/', 'https://fayettehumane.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Fayetteville', 'GA'),
  ('d6000000-0000-4000-8000-000000000021', 'd5000000-0000-4000-8000-000000000021', 'Support Spay/Neuter Events', 'animals', 'Volunteers help at events and outreach for Fix Georgia Pets, which funds low- and no-cost spay/neuter programs to fight pet overpopulation statewide. It is a great fit if you want to address the root cause of shelter overcrowding. Check the site for current opportunities.', array['recurring', 'leadership role'], 18, false, false, true, 'Varies', 'https://fixgeorgiapets.org/', 'https://fixgeorgiapets.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000022', 'd5000000-0000-4000-8000-000000000022', 'Foster or Help at Adoption Events', 'animals', 'Volunteers foster pets, help at adoption centers and outreach events, and support behind-the-scenes projects with Planned PEThood of Georgia in Duluth. Fostering is a big need and a great option for animal lovers. Roles fit many schedules.', array['recurring', 'family friendly'], 16, false, false, true, 'Varies', 'https://pethoodga.org/', 'https://pethoodga.org/', '2026-01-01T00:00:00Z', 'Duluth', 'GA'),
  ('d6000000-0000-4000-8000-000000000023', 'd5000000-0000-4000-8000-000000000023', 'Care for Dogs at a Mountain Rescue', 'animals', 'Volunteers help care for dogs at Homeward Bound Pet Rescue, an all-volunteer, no-kill rescue with a 25-kennel facility in the north Georgia mountains. Expect hands-on animal care and kennel work. It is a great fit if you love dogs and the outdoors.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://hbpr.org/volunteer.html', 'https://hbpr.org/volunteer.html', '2026-01-01T00:00:00Z', 'Ellijay', 'GA'),
  ('d6000000-0000-4000-8000-000000000024', 'd5000000-0000-4000-8000-000000000024', 'Guide Visitors at the Sea Turtle Coast', 'animals', 'Volunteers assist marine educators, interpret exhibits in the Coastal Georgia Gallery, and help at outreach events for the Tybee Island Marine Science Center. It is a great fit if you love the ocean and coastal wildlife. Fill out the contact form to get started.', array['outdoors', 'recurring', 'family friendly'], 16, false, false, true, '3 hrs', 'https://tybeemarinescience.org/volunteer-with-us/', 'https://tybeemarinescience.org/volunteer-with-us/', '2026-01-01T00:00:00Z', 'Tybee Island', 'GA'),
  ('d6000000-0000-4000-8000-000000000025', 'd5000000-0000-4000-8000-000000000025', 'Build Homes in Cobb, Douglas, or Paulding', 'faith', 'Volunteers help build and repair affordable homes or work at the ReStore with NW Metro Atlanta Habitat for Humanity in Smyrna. Build-site volunteers are at least 16 and commit to the full 8-to-4 shift; no experience needed. It is rewarding, team-based work.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://habitatnwma.org/get-involved/', 'https://habitatnwma.org/get-involved/', '2026-01-01T00:00:00Z', 'Smyrna', 'GA'),
  ('d6000000-0000-4000-8000-000000000026', 'd5000000-0000-4000-8000-000000000026', 'Build Homes in the Athens Area', 'faith', 'Volunteers help build affordable homes or work at a ReStore with Athens Area Habitat for Humanity; no experience is required, and build-site volunteers are at least 18. It is rewarding, hands-on work with a lasting result. Contact outreach to sign up.', array['good for crews', 'physical work', 'outdoors'], 18, false, false, true, 'Full day', 'https://www.athenshabitat.com/volunteer/', 'https://www.athenshabitat.com/volunteer/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d6000000-0000-4000-8000-000000000027', 'd5000000-0000-4000-8000-000000000027', 'Build and Repair Homes North of Atlanta', 'faith', 'Volunteers help build and repair affordable homes across four counties with Habitat for Humanity North Central Georgia in Roswell. Build days welcome individuals and groups, with tools and guidance provided. It is meaningful, physical, team-based work.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.habitat-ncg.org/', 'https://www.habitat-ncg.org/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('d6000000-0000-4000-8000-000000000028', 'd5000000-0000-4000-8000-000000000028', 'Maintain Trails and Help with Programs', 'environment', 'Volunteers maintain trails, assist with education programs, and support wildlife monitoring at Sandy Creek Nature Center in Athens. It is hands-on outdoor work in a beautiful setting. Roles suit a range of ages and interests.', array['outdoors', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.sandycreeknaturecenterinc.org/', 'https://www.sandycreeknaturecenterinc.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d6000000-0000-4000-8000-000000000029', 'd5000000-0000-4000-8000-000000000029', 'Help at a Nature Center South of Atlanta', 'environment', 'Volunteers help with programs, animal care, trails, and grounds at Cochran Mill Nature Center in Palmetto, a center largely built by volunteers. It is satisfying outdoor and education work close to Atlanta. Reach out through the site to get involved.', array['outdoors', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://cochranmillnaturecenter.org/', 'https://cochranmillnaturecenter.org/', '2026-01-01T00:00:00Z', 'Palmetto', 'GA'),
  ('d6000000-0000-4000-8000-000000000030', 'd5000000-0000-4000-8000-000000000030', 'Weatherize a Neighbor''s Home', 'environment', 'Volunteers join Southface Institute service projects like the MLK Jr. Day event, weatherizing homes and doing repairs and yardwork to ease costs for elderly neighbors, plus other sustainability work. It is hands-on and high-impact. Great for a group day of service.', array['recurring', 'physical work', 'good for crews'], 16, false, false, true, '3-4 hrs', 'https://www.southface.org/', 'https://www.southface.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000031', 'd5000000-0000-4000-8000-000000000031', 'Rebuild Trails at Line Creek', 'environment', 'Volunteers join workdays to rebuild trails and bridges and help at community events with the Southern Conservation Trust, which protects nature areas like Line Creek near Peachtree City. It is satisfying outdoor stewardship work. Great for individuals and groups.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.sctlandtrust.org/', 'https://www.sctlandtrust.org/', '2026-01-01T00:00:00Z', 'Peachtree City', 'GA'),
  ('d6000000-0000-4000-8000-000000000032', 'd5000000-0000-4000-8000-000000000032', 'Support Local Organic Food', 'environment', 'Volunteers help with events and programs at Georgia Organics, a statewide nonprofit connecting communities with organic food and supporting sustainable farmers. Fill out the volunteer interest form to hear about opportunities. It is a good fit if you care about local, healthy food.', array['recurring', 'good for crews'], 16, false, false, true, 'Varies', 'https://www.georgiaorganics.org/support', 'https://www.georgiaorganics.org/support', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000033', 'd5000000-0000-4000-8000-000000000033', 'Steward a State Park on the Chattahoochee', 'environment', 'Volunteers help with trail work, cleanups, and events with the Friends of Chattahoochee Bend State Park near Newnan, one of Georgia''s largest state parks. It is a great way to protect a beautiful stretch of the Chattahoochee River. Group workdays are welcome.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://bendfriend.org/', 'https://bendfriend.org/', '2026-01-01T00:00:00Z', 'Newnan', 'GA'),
  ('d6000000-0000-4000-8000-000000000034', 'd5000000-0000-4000-8000-000000000034', 'Volunteer at a Macon Hospital', 'medicine', 'Adult volunteers support the patient and family experience across Atrium Health Navicent''s hospitals and children''s hospital in Macon, with a minimum commitment of about 100 hours a year. It is a strong fit if you are exploring a health career. Contact the volunteer coordinator to begin.', array['recurring'], 18, false, false, true, '3-4 hrs / week', 'https://navicenthealth.org/get-involved', 'https://navicenthealth.org/get-involved', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('d6000000-0000-4000-8000-000000000035', 'd5000000-0000-4000-8000-000000000035', 'Support Patients in Savannah', 'medicine', 'Volunteers offer a helping hand and a warm smile to patients and families at St. Joseph''s/Candler in Savannah, supporting care across the health system. You complete an application and orientation first. It is a great fit if you are interested in health care.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.sjchs.org/volunteer-services', 'https://www.sjchs.org/volunteer-services', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d6000000-0000-4000-8000-000000000036', 'd5000000-0000-4000-8000-000000000036', 'Help at a Free Clinic in Athens', 'medicine', 'Volunteers support free, comprehensive health care for uninsured, low-income neighbors at the Athens Wellness Clinic, in medical and administrative roles. It is a meaningful fit if you care about health equity or a health career. Training is provided.', array['recurring'], 18, false, false, true, '2-3 hrs', 'https://athenswellnessclinic.org/', 'https://athenswellnessclinic.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d6000000-0000-4000-8000-000000000037', 'd5000000-0000-4000-8000-000000000037', 'Provide Free Care at Mercy', 'medicine', 'Volunteers, including credentialed medical professionals, provide free health care to low-income, uninsured residents at Mercy Health Center in Athens, where volunteers deliver most of the medical services. It is a strong fit for health professionals and support volunteers alike.', array['recurring'], 18, false, false, true, '3-4 hrs', 'https://www.mercyhealthcenter.net/volunteer', 'https://www.mercyhealthcenter.net/volunteer', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('d6000000-0000-4000-8000-000000000038', 'd5000000-0000-4000-8000-000000000038', 'Serve the Uninsured at Good Sam', 'medicine', 'Volunteers support medical, dental, mental-health, and even farm services at the Good Samaritan Health Center in Atlanta, which relies on 400 volunteers to serve people without insurance. There are clinical and non-clinical roles. It is a great fit if you care about accessible health care.', array['recurring', 'good for crews'], 16, false, false, true, '2-4 hrs', 'https://goodsamatlanta.org/getinvolved/serve/', 'https://goodsamatlanta.org/getinvolved/serve/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000039', 'd5000000-0000-4000-8000-000000000039', 'Be a Writing Mentor for Savannah Youth', 'education', 'Volunteers serve as Writing Fellows, planning and leading weekly workshops that help Savannah middle and high schoolers tell their stories through Deep Center. Fellows co-lead ten to eleven 90-minute sessions in local schools. It is a great fit if you love writing and mentoring.', array['recurring', 'creative work', 'counts for school hours'], 18, false, false, true, '2-3 hrs / week', 'https://www.deepcenter.org/join/', 'https://www.deepcenter.org/join/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d6000000-0000-4000-8000-000000000040', 'd5000000-0000-4000-8000-000000000040', 'Tutor After School in North Fulton', 'education', 'Volunteers tutor and mentor at-risk children in after-school programs, help in the office, or support events with the STAR House Foundation in Roswell. It is a steady, rewarding role helping kids succeed. Register to volunteer through their site.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://www.starhousefoundation.org/register-to-volunteer/', 'https://www.starhousefoundation.org/register-to-volunteer/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('d6000000-0000-4000-8000-000000000041', 'd5000000-0000-4000-8000-000000000041', 'Read at Power Lunch', 'education', 'Volunteers spend one lunch hour a week reading one-on-one with an elementary student through Everybody Wins! Atlanta''s Power Lunch program, all school year. It is a simple, high-impact way to build a child''s love of reading. Register through their site.', array['recurring', 'counts for school hours'], 18, false, false, true, '1 hr / week', 'https://everybodywinsatlanta.org/volunteer/', 'https://everybodywinsatlanta.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000042', 'd5000000-0000-4000-8000-000000000042', 'Help Preschoolers Get Ready to Read', 'education', 'Volunteers work with preschool children in under-resourced Atlanta neighborhoods through Jumpstart, using a proven curriculum to build early language and literacy. Community Corps roles are open to adults, not just college students. It is a meaningful, recurring role.', array['recurring', 'counts for school hours'], 18, false, false, true, '2-3 hrs / week', 'https://www.jstart.org/', 'https://www.jstart.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000043', 'd5000000-0000-4000-8000-000000000043', 'Support Student Success in Metro Atlanta', 'education', 'Volunteers support the work of Learn4Life, a partnership of school districts, businesses, and nonprofits improving academic and workforce outcomes for students across metro Atlanta. Roles vary by initiative. It is a good fit if you want to strengthen the education system.', array['recurring', 'leadership role'], 18, false, false, true, 'Varies', 'https://l4lmetroatlanta.org/', 'https://l4lmetroatlanta.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000044', 'd5000000-0000-4000-8000-000000000044', 'Coach Fitness and Goal-Setting', 'sports', 'Volunteers help lead fitness, literacy, and character programs for youth through the Catch the Stars Foundation in Atlanta. Complete an application and background check to get started. It is a rewarding, active way to mentor young people.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.catchthestars.org/', 'https://www.catchthestars.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000045', 'd5000000-0000-4000-8000-000000000045', 'Mentor Kids at a Macon Club', 'sports', 'Volunteers help with after-school programs, sports, and mentoring at the Boys & Girls Clubs of Central Georgia in Macon, which serves over 1,400 youth a year. It is a great steady role working with kids. Reach out through the site to volunteer.', array['recurring', 'leadership role', 'family friendly'], 18, false, false, true, '2-3 hrs / week', 'https://www.bgccg.org/volunteer', 'https://www.bgccg.org/volunteer', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('d6000000-0000-4000-8000-000000000046', 'd5000000-0000-4000-8000-000000000046', 'Support Kids Facing Homelessness', 'community', 'Volunteers help with projects, meals, and classroom support for children and families experiencing homelessness at Our House in Atlanta. There are roles for individuals and groups. It is a direct way to support kids and parents working toward stability.', array['recurring', 'good for crews', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://ourhousega.org/', 'https://ourhousega.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000047', 'd5000000-0000-4000-8000-000000000047', 'Help at the Children''s Shelter', 'community', 'Volunteers support quality early childhood education and family services that break the cycle of homelessness at the Atlanta Children''s Shelter. There are hands-on and behind-the-scenes roles. It is a meaningful way to help families reach self-sufficiency.', array['recurring', 'good for crews', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://acsatl.org/', 'https://acsatl.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000048', 'd5000000-0000-4000-8000-000000000048', 'Help at the Pantry or Thrift Store', 'community', 'Volunteers provide car-side service at the food pantry, help in the thrift store, or support the mobile pantry at The Place of Forsyth County in Cumming. The food warehouse welcomes volunteers 14 and up. It is a friendly, flexible way to help families near home.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '3 hrs', 'https://www.theplacega.org/new-volunteers', 'https://www.theplacega.org/new-volunteers', '2026-01-01T00:00:00Z', 'Cumming', 'GA'),
  ('d6000000-0000-4000-8000-000000000049', 'd5000000-0000-4000-8000-000000000049', 'Stock the Family Cupboard', 'community', 'Volunteers assist shoppers, restock shelves, and make express boxes in the choice food pantry at The Center for Family Resources in Cobb County, plus events like Thanks for Giving. Groups are welcome on Wednesdays. It is a well-run place to give a few hours.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://thecfr.org/get-involved/', 'https://thecfr.org/get-involved/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d6000000-0000-4000-8000-000000000050', 'd5000000-0000-4000-8000-000000000050', 'Support LGBTQ Youth Facing Homelessness', 'community', 'Volunteers help with street outreach, the thrift store, and assembling food and hygiene packs with Lost-n-Found Youth, which works to end homelessness for LGBTQ youth in Atlanta. There are roles for individuals and groups. It is meaningful, direct-impact work.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://www.lnfy.org/volunteer', 'https://www.lnfy.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000051', 'd5000000-0000-4000-8000-000000000051', 'Sort Food for Gwinnett Families', 'community', 'Volunteers sort and distribute food, support clients, and help maintain the building at The Lawrenceville Cooperative Ministry, which serves Gwinnett County families in need. Shifts are available most days of the week. It is a welcoming, faith-based place to help.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://lawrencevilleco-op.org/volunteer/', 'https://lawrencevilleco-op.org/volunteer/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('d6000000-0000-4000-8000-000000000052', 'd5000000-0000-4000-8000-000000000052', 'Serve Families in Savannah', 'community', 'Volunteers support programs for women, children, and families who are homeless or low-income at Wesley Community Centers of Savannah. There are roles for individuals and groups, including skilled labor. It is a solid way to help neighbors on the coast.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.wesleysav.org/volunteer', 'https://www.wesleysav.org/volunteer', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('d6000000-0000-4000-8000-000000000053', 'd5000000-0000-4000-8000-000000000053', 'Lead Activities for Youth in Columbus', 'community', 'Volunteers run recreational activities like field days, cookouts, and classes, or help with grounds and building projects at Twin Cedars Youth and Family Services near Columbus. Group projects are welcome. It is a fun, hands-on way to support young people.', array['recurring', 'good for crews', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.twincedars.org/get-involved/volunteer-intern/', 'https://www.twincedars.org/get-involved/volunteer-intern/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('d6000000-0000-4000-8000-000000000054', 'd5000000-0000-4000-8000-000000000054', 'Cook Dinner or Mentor a Family', 'community', 'Volunteers provide dinner, childcare, tutoring, and mentoring for families experiencing homelessness through Decatur Cooperative Ministry, including nightly meals at Hagar''s House. There are many ways to help on many schedules. It is a direct way to support families toward stability.', array['recurring', 'good for crews', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.decaturcooperativeministry.org/dcm/volunteer/', 'https://www.decaturcooperativeministry.org/dcm/volunteer/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('d6000000-0000-4000-8000-000000000055', 'd5000000-0000-4000-8000-000000000055', 'Pack Pantry Boxes and Deliver Meals', 'community', 'Volunteers pack pantry donations, deliver groceries and hot meals, and offer Spanish translation with Intown Cares, which works to prevent and reverse homelessness and hunger in intown Atlanta. Groups of up to 15 can sign up. It is flexible, high-impact help.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.intowncares.org/volunteer', 'https://www.intowncares.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000056', 'd5000000-0000-4000-8000-000000000056', 'Support SafePath Behind the Scenes', 'community', 'Volunteers support operations and fundraisers at SafePath Children''s Advocacy Center in Marietta, which reduces trauma for children who have been abused; volunteers do not work directly with the children. A background check and training are required. It is meaningful behind-the-scenes work.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://safepath.org/volunteer/', 'https://safepath.org/volunteer/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('d6000000-0000-4000-8000-000000000057', 'd5000000-0000-4000-8000-000000000057', 'Advocate for a Child in Foster Care', 'community', 'Volunteers train as Court Appointed Special Advocates through Georgia CASA to speak up for children in foster care - visiting the child, gathering information, and reporting to the court. Training is about 40 hours, and volunteers are 21 and up. It is a deep, life-changing commitment.', array['recurring', 'leadership role'], 21, false, false, true, '2-4 hrs / month', 'https://www.gacasa.org/become-a-volunteer/', 'https://www.gacasa.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000058', 'd5000000-0000-4000-8000-000000000058', 'Help People Keep Their Pets', 'community', 'Volunteers help with special events, community outreach, and vaccine clinics with PALS Atlanta, which supports pets of people living with serious illness, seniors, and veterans. There are behind-the-scenes and front-facing roles. It is a great fit if you love both people and animals.', array['recurring', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://www.palsatlanta.org/get-involved/', 'https://www.palsatlanta.org/get-involved/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000059', 'd5000000-0000-4000-8000-000000000059', 'Pack Groceries in Cherokee County', 'food', 'Volunteers sort, pack, and distribute groceries to families facing food insecurity at the Never Alone Community Food Pantry in Woodstock, where volunteers give over 1,000 hours a month. It is a friendly, hands-on way to fight hunger. Sign up through their volunteer portal.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.neveralone.org/', 'https://www.neveralone.org/', '2026-01-01T00:00:00Z', 'Woodstock', 'GA'),
  ('d6000000-0000-4000-8000-000000000060', 'd5000000-0000-4000-8000-000000000060', 'Rescue Food and Serve Meals', 'food', 'Volunteers help recover surplus food and serve healthy meals to people who are hungry and homeless through Umi Feeds, including a weekly mobile market in Atlanta. It is active, people-first work against food waste and hunger. Roles fit many schedules.', array['good for crews', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://umifeeds.org/', 'https://umifeeds.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000061', 'd5000000-0000-4000-8000-000000000061', 'Help Run a Farmers Market', 'gardening', 'Volunteers help set up, run the info booth, and clean up at the Freedom Farmers Market at the Carter Center, bringing local sustainably grown food to intown Atlanta. Shifts run Saturday mornings. It is a fun, outdoors way to support local food.', array['outdoors', 'good for crews', 'recurring'], 14, false, false, true, '2-4 hrs', 'https://freedomfarmersmkt.com/get-involved', 'https://freedomfarmersmkt.com/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000062', 'd5000000-0000-4000-8000-000000000062', 'Support Markets and Community Gardens', 'gardening', 'Volunteers help run neighborhood farmers markets and pitch in on community-garden workdays around metro Atlanta with Community Farmers Markets. No experience is needed for garden days. It is a great way to explore urban agriculture and local food.', array['outdoors', 'good for crews', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://cfmatl.org/get-involved/volunteers/', 'https://cfmatl.org/get-involved/volunteers/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000063', 'd5000000-0000-4000-8000-000000000063', 'Tend the Columbus Botanical Garden', 'gardening', 'Volunteers tend beds and daylilies, arrange flowers, prune plants, and lead tours at the Columbus Botanical Garden, earning fun perks at 50 and 100 hours. It is hands-on outdoor work for garden lovers. Register through their volunteer page.', array['outdoors', 'physical work', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://www.columbusbotanicalgarden.org/volunteer', 'https://www.columbusbotanicalgarden.org/volunteer', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('d6000000-0000-4000-8000-000000000064', 'd5000000-0000-4000-8000-000000000064', 'Mentor Students in STEAM', 'tech', 'Volunteers mentor and guide students through hands-on STEAM workshops with STE(A)M Truck, an Atlanta nonprofit that brings high- and low-tech learning to youth. It is a fun way to inspire future builders and innovators. Roles support immersive, project-based sessions.', array['recurring', 'leadership role', 'counts for school hours'], 18, false, false, true, '2-3 hrs', 'https://www.steamtruck.org/volunteer', 'https://www.steamtruck.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000065', 'd5000000-0000-4000-8000-000000000065', 'Help at a Computer Giveaway', 'tech', 'Volunteers load trailers, assist in technology classes, hand out computers at giveaways, and capture photos for Compudopt, which provides free computers and tech education to under-resourced youth. There are in-person and virtual roles. It is a great fit if you care about digital equity.', array['recurring', 'good for crews', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://www.compudopt.org/volunteer-atlanta', 'https://www.compudopt.org/volunteer-atlanta', '2026-01-01T00:00:00Z', 'Forest Park', 'GA'),
  ('d6000000-0000-4000-8000-000000000066', 'd5000000-0000-4000-8000-000000000066', 'Refurbish Computers for Digital Equity', 'tech', 'Volunteers disassemble, test, clean, and prepare donated computers in the warehouse at PCs for People''s Atlanta location, helping make technology affordable for people in need. No special skills are required for many tasks. It is satisfying, hands-on work with real impact.', array['recurring', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://www.pcsforpeople.org/volunteer-interest-form/', 'https://www.pcsforpeople.org/volunteer-interest-form/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000067', 'd5000000-0000-4000-8000-000000000067', 'Renovate a Veteran''s Home', 'veterans', 'Volunteers help with home modifications and renovations that provide housing solutions for disabled and aging veterans through the Purple Heart Homes metro Atlanta chapter. Build days are hands-on and team-based. It is a meaningful way to thank those who served.', array['recurring', 'physical work', 'good for crews'], 18, false, false, true, 'Full day', 'https://www.purplehearthomesusa.org/', 'https://www.purplehearthomesusa.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('d6000000-0000-4000-8000-000000000068', 'd5000000-0000-4000-8000-000000000068', 'Pack Care Boxes for Service Members', 'veterans', 'Volunteers pack and ship care boxes matched to the wish lists of deployed, injured, aging, and homeless service members and veterans through HeroBox in Peachtree City. It is a family-friendly, feel-good way to thank those who serve. Great for individuals and groups.', array['good for crews', 'family friendly', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://www.herobox.org/volunteer', 'https://www.herobox.org/volunteer', '2026-01-01T00:00:00Z', 'Peachtree City', 'GA'),
  ('d6000000-0000-4000-8000-000000000069', 'd5000000-0000-4000-8000-000000000069', 'Support Special Operations Families', 'veterans', 'Volunteers help with events and programs that support wounded and fallen Special Operations Forces and their families through Operation One Voice, a Georgia-based, volunteer-driven nonprofit. It is a great fit if you want to honor and support military families. Reach out through the site to help.', array['recurring', 'good for crews', 'leadership role'], 18, false, false, true, 'Varies', 'https://o1v.org/', 'https://o1v.org/', '2026-01-01T00:00:00Z', 'Hoschton', 'GA'),
  ('d6000000-0000-4000-8000-000000000070', 'd5000000-0000-4000-8000-000000000070', 'Help Produce LGBTQIA+ Theatre', 'art', 'Volunteers usher, help backstage, and support events and productions at Out Front Theatre Company, Georgia''s LGBTQIA+ theatre in Atlanta. Whatever your skill level or interest, they can find a place for you. It is a welcoming way to be part of the arts scene.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://outfronttheatre.com/staff/volunteer/', 'https://outfronttheatre.com/staff/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA')
